evaluateAndRenderTradeDetails = async function() {
  var endIdx, err, newResult, result, runObjects, startIdx, tkns;
  log("evaluateAndRenderTradeDetails");
  try {
    log(_tradeKey);
    result = (await engine.getTradeResultDetails(_tradeKey));
    // olog result
    log(Object.keys(result));
  } catch (error) {
    err = error;
    console.error(err);
    return;
  }
  //# Maybe no update at all?
  if (result.direction !== _direction) { // somehow we should be changing direction on this trade...
    newResult = {
      direction: result.direction,
      tradeKey: _tradeKey,
      eventLabel: _eventLabel
    };
    return displayDetails(newResult);
  }
  displaySummary(result);
  await letMainThreadRun();
  runObjects = result.infoObjects.filter(function(el) {
    return el.tradable;
  });
  _allResults = runObjects.map(transformRunObjToDetailsResult);
  renderDetailsTable();
  tkns = _trade.split("-");
  startIdx = parseInt(tkns[0]);
  endIdx = parseInt(tkns[1]);
  log("after general rendering");
  olog({_tradeKey, _trade});
  olog({startIdx, endIdx});
  await letMainThreadRun();
  charting.reset();
  charting.prepareData(result.avgDailyReturn, result.nextDate);
  charting.setSelectedRegion({startIdx, endIdx});
};

