onSortColumnClick = function(evnt) {
  var key;
  key = evnt.target.getAttribute("data-sort-key");
  log(`onSortColumnClick: ${key}`);
  if (sortColumn === key) {
    sortAscending = !sortAscending; // Toggle direction
  } else {
    sortColumn = key;
    sortAscending = false; // New column: start descending
  }
  olog({sortColumn, sortAscending});
  renderDetailsTable();
};

sortAllResults = function(results) {
  var compareFn, sorted;
  sorted = [...results]; // Copy to avoid mutating original
  compareFn = (function() {
    switch (sortColumn) {
      case "eventD":
        return function(a, b) {
          return (new Date(a.eventD)).getTime() - (new Date(b.eventD)).getTime();
        };
      case "profit":
        if (_direction === "Short") {
          return function(a, b) {
            return b.deltaF - a.deltaF;
          };
        } else {
          return function(a, b) {
            return a.deltaF - b.deltaF;
          };
        }
        break;
      // log("sorting profit... while #{_direction}")
      // if _direction == "Long"
      //     log "actually in LONG" # I can see I am here in this branch
      //     (a, b) -> a.deltaF - b.deltaF # must be right - but sorting profit in Long is always wrong
      //     # (a, b) -> b.deltaF - a.deltaF # remarkably swithing things up here does not change the result!
      // if _direction == "Short" 
      //     log "actually in SHORT"
      //     (a, b) -> b.deltaF - a.deltaF
      //     # (a, b) -> a.deltaF - b.deltaF # makes short be wrong... as expected

        // when "profitA"
      //     (a, b) -> a.entryAr * a.deltaF - b.entryAr * b.deltaF ## TODO adjust to what we actually have available
      case "maxRise":
        log("sorting maxRise");
        return function(a, b) {
          return a.maxRiseF - b.maxRiseF;
        };
      // when "maxRiseA"
      //     (a, b) -> (a.startAr * a.maxRiseP) - (b.startAr * b.maxRiseP)
      case "maxDrop":
        log("sorting maxDrop");
        return function(a, b) {
          return (-a.maxDropF) - (-b.maxDropF); // Flipped for max Drops
        };
      default:
        // when "maxDropA"
        //     (a, b) -> (-a.startAr * a.maxDropP) - (-b.startAr * b.maxDropP)
        return function(a, b) {
          return 0;
        };
    }
  })();
  sorted.sort(compareFn);
  if (!sortAscending) {
    sorted.reverse();
  }
  return sorted;
};

//###########################################################
transformRunObjToDetailsResult = function(runObj) {
  var detailsRes, eventDate;
  detailsRes = Object.create(null);
  eventDate = runObj.key.split("@")[1];
  detailsRes.entryD = runObj.entryDate;
  detailsRes.eventD = eventDate;
  detailsRes.exitD = runObj.exitDate;
  detailsRes.entryAba = runObj.entryCba;
  detailsRes.exitAba = runObj.entryCba * (runObj.deltaF + 1.0);
  detailsRes.missingSF = runObj.missingSF;
  detailsRes.deltaF = runObj.deltaF;
  detailsRes.maxRiseF = runObj.maxRiseF;
  detailsRes.maxRiseAr = runObj.maxRiseAr;
  detailsRes.maxRiseAba = runObj.entryCba * runObj.maxRiseF;
  detailsRes.maxRiseMissingSF = runObj.maxRiseMissingSF;
  detailsRes.maxDropF = runObj.maxDropF;
  detailsRes.masDropAr = runObj.maxDropAr;
  detailsRes.maxDropAba = runObj.entryCba * runObj.maxDropF;
  detailsRes.maxDropMissingSF = runObj.maxDropMissingSF;
  return detailsRes;
};

//###########################################################
formatPercent = function(value) {
  var sign;
  sign = value >= 0 ? "+" : "";
  return `${sign}${value.toFixed(1)}%`;
};

formatAbsoluteDelta = function(value, missingSF) {
  var html, sign;
  sign = value >= 0 ? "+" : "";
  html = formatAbsolutePrice(value, missingSF);
  return `${sign}${html}`;
};

