//###########################################################
getNrTradeDays = function() {
  var entryIdx, exitIdx, tkns;
  // log "getNrTradeDays"
  tkns = _trade.split("-");
  if (tkns.length !== 3) {
    throw new Error("invalid _trade!");
  }
  entryIdx = parseInt(tkns[0]);
  exitIdx = parseInt(tkns[1]);
  return exitIdx - entryIdx;
};

//###########################################################
getEntryIdxForDisplay = function() {
  var entryIdx, halfIdx, idx, tkns;
  if (_trade == null) {
    throw new Error("no _trade available!");
  }
  tkns = _trade.split("-");
  if (tkns.length !== 3) {
    throw new Error("invalid _trade!");
  }
  entryIdx = parseInt(tkns[0]);
  halfIdx = parseInt(tkns[2]);
  idx = entryIdx - halfIdx;
  if (idx > 0) {
    return "+" + idx;
  } else {
    return "" + idx;
  }
};

//###########################################################
getExitIdxForDisplay = function() {
  var exitIdx, halfIdx, idx, tkns;
  log("getEntryIdxForDisplay");
  if (_trade == null) {
    throw new Error("no _trade available!");
  }
  tkns = _trade.split("-");
  if (tkns.length !== 3) {
    throw new Error("invalid _trade!");
  }
  exitIdx = parseInt(tkns[1]);
  halfIdx = parseInt(tkns[2]);
  idx = exitIdx - halfIdx;
  if (idx > 0) {
    return "+" + idx;
  } else {
    return "" + idx;
  }
};

